using MeineErsteWebApp.Models;
using Microsoft.Data.Sqlite;
namespace MeineErsteWebApp.Repositories;
public class TodoRepository
{
    private readonly string _connectionString;
    public TodoRepository(IConfiguration config) => _connectionString = config.GetConnectionString("Todos") ?? "Data Source=todos.db";
    private SqliteConnection Open() { var c = new SqliteConnection(_connectionString); c.Open(); return c; }
    public void Initialize() { using var c=Open(); using var q=c.CreateCommand(); q.CommandText="CREATE TABLE IF NOT EXISTS Categories(Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE); CREATE TABLE IF NOT EXISTS Todos(Id INTEGER PRIMARY KEY AUTOINCREMENT, Title TEXT NOT NULL, Description TEXT, DueDate TEXT, Priority INTEGER NOT NULL, Done INTEGER NOT NULL DEFAULT 0, CreatedAt TEXT NOT NULL, CategoryId INTEGER NULL REFERENCES Categories(Id)); INSERT OR IGNORE INTO Categories(Name) VALUES ('Allgemein'),('Arbeit'),('Privat');"; q.ExecuteNonQuery(); }
    public List<Category> GetCategories() { using var c=Open(); using var q=c.CreateCommand(); q.CommandText="SELECT Id,Name FROM Categories ORDER BY Name"; using var r=q.ExecuteReader(); var x=new List<Category>(); while(r.Read()) x.Add(new(r.GetInt32(0),r.GetString(1))); return x; }
    private static Todo Map(SqliteDataReader r) => new() { Id=r.GetInt32(0), Title=r.GetString(1), Description=r.IsDBNull(2)?null:r.GetString(2), DueDate=r.IsDBNull(3)?null:DateTime.Parse(r.GetString(3)), Priority=r.GetInt32(4), Done=r.GetInt32(5)==1, CreatedAt=DateTime.Parse(r.GetString(6)), CategoryId=r.IsDBNull(7)?null:r.GetInt32(7), CategoryName=r.IsDBNull(8)?null:r.GetString(8) };
    public List<Todo> GetAll(string status, int? priority, int? category, string sort) { using var c=Open(); using var q=c.CreateCommand(); q.CommandText="SELECT t.Id,t.Title,t.Description,t.DueDate,t.Priority,t.Done,t.CreatedAt,t.CategoryId,c.Name FROM Todos t LEFT JOIN Categories c ON c.Id=t.CategoryId WHERE ($status='alle' OR t.Done=CASE WHEN $status='erledigt' THEN 1 ELSE 0 END) AND ($priority IS NULL OR t.Priority=$priority) AND ($category IS NULL OR t.CategoryId=$category) ORDER BY " + (sort=="prioritaet"?"t.Priority DESC,":"t.DueDate IS NULL,t.DueDate,") + " t.CreatedAt DESC"; q.Parameters.AddWithValue("$status",status); q.Parameters.AddWithValue("$priority",(object?)priority??DBNull.Value); q.Parameters.AddWithValue("$category",(object?)category??DBNull.Value); using var r=q.ExecuteReader(); var x=new List<Todo>(); while(r.Read())x.Add(Map(r)); return x; }
    public Todo? GetById(int id) { using var c=Open(); using var q=c.CreateCommand(); q.CommandText="SELECT t.Id,t.Title,t.Description,t.DueDate,t.Priority,t.Done,t.CreatedAt,t.CategoryId,c.Name FROM Todos t LEFT JOIN Categories c ON c.Id=t.CategoryId WHERE t.Id=$id"; q.Parameters.AddWithValue("$id",id); using var r=q.ExecuteReader(); return r.Read()?Map(r):null; }
    public void Add(Todo t) { using var c=Open(); using var q=c.CreateCommand(); q.CommandText="INSERT INTO Todos(Title,Description,DueDate,Priority,Done,CreatedAt,CategoryId) VALUES($title,$description,$due,$priority,0,$created,$category)"; Fill(q,t); q.ExecuteNonQuery(); }
    public void Update(Todo t) { using var c=Open(); using var q=c.CreateCommand(); q.CommandText="UPDATE Todos SET Title=$title,Description=$description,DueDate=$due,Priority=$priority,CategoryId=$category WHERE Id=$id"; Fill(q,t); q.Parameters.AddWithValue("$id",t.Id); q.ExecuteNonQuery(); }
    public void Toggle(int id) { using var c=Open(); using var q=c.CreateCommand(); q.CommandText="UPDATE Todos SET Done=1-Done WHERE Id=$id"; q.Parameters.AddWithValue("$id",id); q.ExecuteNonQuery(); }
    public void Delete(int id) { using var c=Open(); using var q=c.CreateCommand(); q.CommandText="DELETE FROM Todos WHERE Id=$id"; q.Parameters.AddWithValue("$id",id); q.ExecuteNonQuery(); }
    private static void Fill(SqliteCommand q, Todo t) { q.Parameters.AddWithValue("$title",t.Title); q.Parameters.AddWithValue("$description",(object?)t.Description??DBNull.Value); q.Parameters.AddWithValue("$due",t.DueDate?.ToString("yyyy-MM-dd")??(object)DBNull.Value); q.Parameters.AddWithValue("$priority",t.Priority); q.Parameters.AddWithValue("$created",t.CreatedAt.ToString("O")); q.Parameters.AddWithValue("$category",(object?)t.CategoryId??DBNull.Value); }
}
